examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchColorPicker(
        value = color,
        onValueChange = { color = it },
        label = {{label}},
    )
    MonarchText(text = "Selected: " + color)
}

